functionsetCookie(name,value,days=365){
constexpires=newDate(Date.now()+days*864e5).toUTCString();
constdomain=location.hostname.split('.').slice(-2).join('.');//saveonrootdomain
document.cookie=`${name}=${encodeURIComponent(value)};expires=${expires};path=/;domain=.blooket.com;SameSite=Lax`;
}

functiongetCookie(name){
constmatch=document.cookie.match(newRegExp('(^|)'+name+'=([^;]+)'));
returnmatch?decodeURIComponent(match[2]):null;
}

functionareSweetAlertsEnabled(){
constcookieValue=getCookie("sweetAlertsEnabled");
returncookieValue===null?true:cookieValue==="true";
}

