formatNumber(input){
const[number,exponent]=(input=parseFloat(input)).toLocaleString(undefined,{
notation:"engineering"
}).toLowerCase().split("e");
if(exponent<15)returnnumber+["","k","M","B","T"][exponent/3];
const[num,exp]=input.toLocaleString(undefined,{
notation:"scientific"
}).toLowerCase().split("e");
returnnum+"\xd710"+exp.split("").reduce((a,b)=>a+Logs.exponents[b],"");
},
