cheats:[{
name:"MaxItems",
description:"Maxesoutitemsintheshop(soloonly)",
run:function(){
constnode=getStateNode('cafe');
if(!node?.memoizedState)returnconsole.log("❌Failedtofindgamestate.");

consthook=getHook(node,4);
if(hook?.memoizedState?.Toast){
constnewLevels={...hook.memoizedState};
Object.keys(newLevels).forEach(key=>{
if(typeofnewLevels[key]==='number')newLevels[key]=5;
});
hook.queue.dispatch(newLevels);
}
},
},
{
name:"SetCash",
description:"Setscafecash(onlyworksinsolo)",
inputs:[{name:"Amount",type:"number"}],
run:function(cafeCash){
constnewAmount=cafeCash||1000000;
if(isNaN(newAmount))return;

constnode=getStateNode('cafe');
if(!node?.memoizedState)returnconsole.log("❌Failedtofindgamestate.");

lethook=node.memoizedState;
letdepth=0;

while(hook){
if(depth>7&&typeofhook.memoizedState==='number'&&hook.queue){
hook.queue.dispatch(newAmount);
returnconsole.log(`✅Cashsetto${newAmount.toLocaleString()}!`);
}
hook=hook.next;
depth++;
}
},
},
{
name:"StockFood",
description:"Stocksallfoodto999(Notusableinshop)(Soloonly)",
run:function(){
constnode=getStateNode('cafe');
if(!node?.memoizedState)returnconsole.log("❌Failedtofindgamestate.");

consthook4=getHook(node,4);
consthook5=getHook(node,5);

if(hook4?.memoizedState?.Toast&&hook5?.memoizedState){
constnewLevels={...hook4.memoizedState};
constnewStock={...hook5.memoizedState};

Object.keys(newLevels).forEach(key=>{
if(typeofnewLevels[key]==='number')newLevels[key]=5;
});
Object.keys(newStock).forEach(key=>{
if(typeofnewStock[key]==='number')newStock[key]=999;
});

hook4.queue.dispatch(newLevels);
hook5.queue.dispatch(newStock);
}
},
},
{
name:"MakeCustomersOP",
description:"MakesallcustomerspayaLOT(onlyworksinsolo)",
run:function(){
if(window.opCustomerInterval)clearInterval(window.opCustomerInterval);

constOP_VALUE=99999999999999;

window.opCustomerInterval=setInterval(()=>{
constnode=getStateNode('cafe');
if(!node?.memoizedState)return;

lethook=node.memoizedState;
while(hook){
if(hook.memoizedStateinstanceofMap){
hook.memoizedState.forEach((val)=>{
if(val?.order?.value!==OP_VALUE){
val.order.value=OP_VALUE;
}
});
}
hook=hook.next;
}
},500);

}
},
{
name:"MakeUpgradesCheap",
description:"Makesmostupgradescheapwithinsaneprofits",
run:function(){
constnode=getStateNode('cafe');
if(!node?.memoizedState)returnconsole.log("❌Failedtofindgamestate.");

consthook=getHook(node,1);
if(hook?.memoizedState?.toast?.prices){
constnewDefs={...hook.memoizedState};

Object.keys(newDefs).forEach(key=>{
constitem=newDefs[key];
if(item?.prices&&item?.profits){
newDefs[key]={
...item,
prices:newArray(item.prices.length).fill(1),
profits:newArray(item.profits.length).fill(9e99)
};
newDefs[key].profits[0]=0;
}
});

hook.queue.dispatch(newDefs);
}
}
}
],
