functioncreateInput(label){
constwrap=document.createElement("div");
wrap.style.display="flex";
wrap.style.flexDirection="column";
wrap.style.alignItems="center";
wrap.style.gap="6px";

constl=document.createElement("label");
l.textContent=label;
l.style.color="#fff";
l.style.fontWeight="600";

consti=document.createElement("input");
i.type="number";
i.min=0;
i.value=0;
i.className="blookInput";

wrap.append(l,i);
editorContainer.appendChild(wrap);
returni;
}

