functionparseTime(d){
consthour=d.getHours()%12==0?12:d.getHours()%12;
constminutes=d.getMinutes().toString().padStart(2,"0");
return`${hour}:${minutes}${d.getHours()>=12?"PM":"AM"}`;
}

functionparseDate(d){
constmonth=["January","February","March","April","May","June","July","August","September","October","November","December"][d.getMonth()];
return`${month}${d.getDate()}${getOrdinal(d.getDate())},${d.getFullYear()}-${parseTime(d)}`;
}

