//CSPDetectionFunction
functiondetectCSP(){
letcspDetected=false;

//Method1:Trytoexecuteinlinescript
try{
consttestScript=document.createElement('script');
testScript.textContent='window.__cspTestPassed=true;';
document.head.appendChild(testScript);
document.head.removeChild(testScript);

if(!window.__cspTestPassed){
cspDetected=true;
}
deletewindow.__cspTestPassed;
}catch(e){
cspDetected=true;
}

//Method2:CheckforCSPmetatags
constcspMeta=document.querySelector('meta[http-equiv="Content-Security-Policy"]');
if(cspMeta&&cspMeta.content.includes('script-src')){
cspDetected=true;
}

returncspDetected;
}

