functiongetHook(node,index){
lethook=node.memoizedState;
leti=0;
while(hook&&i<index){
hook=hook.next;
i++;
}
returnhook;
}

functionGetPhaser(){
if(!window.Phaser){
alert("Phasernotfound!");
returnnull;
}

window._groups??=newSet();
window._sprites??=newSet();

if(!window._phaserSceneHooked){
constSceneManager=window.Phaser.Scenes.SceneManager.prototype;
constoriginalUpdate=SceneManager.update;

SceneManager.update=function(time,delta){
originalUpdate.call(this,time,delta);
window._SCENE=this.scenes.find(s=>s.sys?.isActive()&&s.sys?.settings?.key!=='Boot');
};

window._phaserSceneHooked=true;
}

if(!window._phaserGroupHooked&&window.Phaser.GameObjects?.Group?.prototype){
constGroup=window.Phaser.GameObjects.Group.prototype;
constoriginalUpdate=Group.preUpdate||Group.update;

if(originalUpdate){
Group.preUpdate=function(...args){
window._groups.add(this);
returnoriginalUpdate?.apply(this,args);
};
}

window._phaserGroupHooked=true;
}

if(!window._phaserSpriteHooked&&window.Phaser.GameObjects?.Sprite?.prototype){
constSprite=window.Phaser.GameObjects.Sprite.prototype;
constoriginalUpdate=Sprite.preUpdate;

Sprite.preUpdate=function(time,delta){
window._sprites.add(this);

constkey=this.texture?.key;
if(key?.includes('player')||key?.includes('blook')||this.name?.includes('player')){
window._player=this;
}

returnoriginalUpdate?.apply(this,arguments);
};

window._phaserSpriteHooked=true;
}

if(!window._phaserBodyHooked&&window.Phaser.Physics?.Arcade?.Body?.prototype){
constBody=window.Phaser.Physics.Arcade.Body.prototype;
constoriginalUpdate=Body.preUpdate;

Body.preUpdate=function(){
constkey=this.gameObject?.texture?.key;
if(key?.includes('player')||key?.includes('blook')){
window._playerBody=this;
}

returnoriginalUpdate?.apply(this,arguments);
};

window._phaserBodyHooked=true;
}

if(!window._phaserWorldHooked&&window.Phaser.Physics?.Arcade?.World?.prototype){
constWorld=window.Phaser.Physics.Arcade.World.prototype;

constcheckInvincibility=(body1,body2)=>
window._invincibilityActive&&(body1===window._playerBody||body2===window._playerBody);

if(World.collideObjects){
constoriginalCollide=World.collideObjects;
World.collideObjects=function(body1,body2,...args){
returncheckInvincibility(body1,body2)?false:originalCollide.apply(this,[body1,body2,...args]);
};
}

if(World.separate){
constoriginalSeparate=World.separate;
World.separate=function(body1,body2,...args){
returncheckInvincibility(body1,body2)?false:originalSeparate.apply(this,[body1,body2,...args]);
};
}

window._phaserWorldHooked=true;
}

if(!window._SCENE){
constscenes=window.Phaser.Scene.SceneManager?.prototype?.scenes||[];
window._SCENE=scenes.find(s=>s?.sys?.isActive?.()&&s.sys?.settings?.key!=='Boot');
}

if(!window._SCENE)returnnull;

returnnewProxy(window._SCENE,{
get(target,prop){
constaccessors={
groups:window._groups,
sprites:window._sprites,
player:window._player,
playerBody:window._playerBody,
scene:target
};
returnaccessors[prop]??target[prop];
}
});
}

